import{_ as t,o,c as e,ag as a}from"./chunks/framework.DaAXJYxM.js";const d=JSON.parse('{"title":"第51章 正在输入","description":"","frontmatter":{},"headers":[],"relativePath":"第51章_正在输入.md","filePath":"第51章_正在输入.md"}'),_={name:"第51章_正在输入.md"};function u(r,p,q,n,s,c){return o(),e("div",null,[...p[0]||(p[0]=[a('<h1 id="第51章-正在输入" tabindex="-1">第51章 正在输入 <a class="header-anchor" href="#第51章-正在输入" aria-label="Permalink to &quot;第51章 正在输入&quot;">​</a></h1><p>那年四月，我发出去两个字：早点睡。</p><p>在那之前我写了九百多个字。</p><p>起因很小。</p><p>那天晚上她跟我讲她们宿舍的事，讲到一半她说，我今天被问了一个问题。</p><p>我说，谁问。</p><p>她说，我朋友。</p><p>她说，她问我，你俩现在到底算什么。</p><p>我说，你怎么说。</p><p>她停了一下。</p><p>她说，我说没有。</p><p>她说，我说我一个人。</p><p>我说，你为什么说没有。</p><p>她说，因为我说有，她就要问我叫什么，哪个学校，怎么认识的。</p><p>她说，我一个都答不上来。</p><p>她说，我答不上来就意味着我要么撒谎要么全说。</p><p>她说，我不想撒谎，我也不能全说。</p><p>她说，所以我就说没有。</p><p>我说，哦。</p><p>她说，你这个哦是什么意思。</p><p>我说，没有意思。</p><p>她说，你这个哦就是有意思。</p><p>我说，那你说怎么办。</p><p>她说，我没说怎么办。</p><p>她说，我就是告诉你她问了。</p><p>我说，你告诉我这个，是想让我知道我在别人那儿是没有。</p><p>她说，我没这么说。</p><p>我说，你就是这个意思。</p><p>她说，行，我是这个意思。</p><p>那一下她接得太快了。</p><p>快到我在屏幕前面愣了。</p><p>因为这意味着她想过这个问题，想了很多遍，答案就摆在手边，随手能拿。</p><p>而她一直不跟我说。</p><p>那天晚上她下线以前说了一句。</p><p>她说，你别多想。</p><p>我说，我没有。</p><p>她说，你有。</p><p>她说，你多想的时候打字会变慢。</p><p>我说，我看不到这个。</p><p>她说，我看得到。</p><p>她说完这句就下了。</p><p>那天夜里一点多，我没睡。</p><p>我把手机放在肚子上，看天花板，开始在心里给她写信。</p><p>我在心里写了很久，然后我坐起来，打开灯，拿纸写。</p><p>第一版我写了九百多字。</p><p>写的是什么，我现在还记得个大概。</p><p>我写了我们从高一那个寒假开始，每一次她说&quot;别找我&quot;，我第二天还在。我写了本子，写了瓶盖，写了她说她在楼梯间抽烟。我写了她给我那张单子，我写了六个快递单号。</p><p>然后我写了那三行。</p><p>我写的核心是三行：</p><p>你说没有的时候，你说的是别人那儿。</p><p>我这儿不是。</p><p>我要你在我这儿，别说没有。</p><p>我写完，从头读了一遍。</p><p>读到第二遍，我把&quot;我要你&quot;那一句改了。</p><p>我改成&quot;我希望你&quot;。</p><p>因为&quot;我要你&quot;太硬了，她会以为我在要一个名分。</p><p>我不是要名分。我是要她别在她朋友那儿把自己说成一个人。</p><p>第三遍我把&quot;我希望你&quot;改回&quot;我要你&quot;。</p><p>因为&quot;希望&quot;是把她放在远处说的话。</p><p>我把那一版留在纸上，在手机上重新打。</p><p>打到三百字左右，我停了。</p><p>我发现我在解释。</p><p>我在跟她解释&quot;我这个人是怎么想的&quot;，一件一件地铺，铺了很久。</p><p>我忽然想起她跟我说过的一句话。</p><p>她说过：你讲话一乱就是这个毛病，前面说的跟后面接不上。</p><p>我在解释的时候，就是在往前铺，而后面的话永远到不了。</p><p>我把三百字删了。</p><p>第二版我重打，压到一百二十字。</p><p>那一版我现在觉得是最好的一版。</p><p>我写的是：你说没有，我听懂了。我不管别人那儿。你别在我这儿说没有。</p><p>一百二十个字，一句话一个句号。</p><p>我看着那一版，看了两分钟。</p><p>然后我想到一件事。</p><p>她那天说的最后一句是&quot;你多想的时候打字会变慢&quot;。</p><p>也就是说，她看得见我在写。</p><p>她看得见，她就会知道我又在铺。</p><p>她最烦的就是这个。</p><p>我删了第二版。</p><p>第三版我打的是：早点睡。</p><p>三个字。</p><p>我打那三个字的时候，手特别稳。</p><p>我按了发送。</p><p>发出去以后，屏幕上出现了那行字。</p><p>她说，我知道你写了。</p><p>我说，我没写。</p><p>她说，你正在输入输入了四分钟。</p><p>她说，我看着那四个字在那儿亮，亮了四分钟，灭了一次，又亮。</p><p>她说，最后你发了三个字。</p><p>我坐在那儿，一句话都说不出来。</p><p>然后她发了一句。</p><p>她说，你下次要是又写，你别删。</p><p>我说，为什么。</p><p>她说，因为你删的那部分才是你要说的。</p><p>她说，你发出来的那个，是给我看的门面。</p><p>她说，我看了两年门面了。</p><p>我把手机扣在被子上了。</p><p>那天夜里我想明白了一件事，一件我一直不愿意承认的事。</p><p>我以为我删字，是为了不打扰她。</p><p>不是为了这个。</p><p>我删字，是因为我害怕她读完。</p><p>发三个字，她最多回一句。</p><p>发九百字，她就得认真回应，而她一旦认真回应，她就得承认她被我打动了。</p><p>她被谁打动，在她那边是危险的事。</p><p>所以我不发。</p><p>我用&quot;早点睡&quot;替她把门关上。</p><p>她安全，我也安全。</p><p>我以为这是懂事。</p><p>第二天我试过一次。</p><p>那天她心情好，讲了一件很长的学校的事。讲完她问我，那你今天呢。</p><p>我说，我今天有点事想说。</p><p>她说，你说。</p><p>我打了六十个字。</p><p>六十个字发出去以后，她隔了很久。</p><p>久到我去看了一眼网有没有断。</p><p>然后她回：今天少了八百三。</p><p>我看着那五个字，笑不出来。</p><p>她说，你别紧张，我猜的。</p><p>她说，你昨天那个输入时长，我按分钟估的。</p><p>我说，你估算这个干什么。</p><p>她没答。</p><p>那晚她最后发的是：你以后想说就说，你不用替我省。</p><p>我说，省什么。</p><p>她说，省你自己。</p><p>那一年里我发出去的最长一条，是四十三个字。</p><p>她发给我最长的一条，我数过，四百一十七。</p><p>那天夜里我在本子上写了一条，写完自己看着觉得像一份规矩。</p><p>我写：以后我在她那儿，正在输入不要超过十秒。</p><p>我把这条抄在规程那一页的背面。</p><p>我没告诉她。</p><p>我这一辈子最擅长的事，就是给自己定一条根本做不到的规矩，然后每天看着它。</p><p>后来我到大二才算明白她那句“省你自己”是什么意思。</p><p>我不是怕她麻烦。</p><p>我是怕她看见一个需要她的人。</p><p>而一个需要她的人，在她那边不是惊喜，是一张她兑不出的票。</p>',134)])])}const l=t(_,[["render",u]]);export{d as __pageData,l as default};
